/**
 * Strip FBV verse commentaries from text (client-side fallback).
 * FBV embeds commentaries like "1:5. It is significant..." or "1:1. Or "Christ." ..." inline.
 */
export function stripFbvCommentary(text: string, chapter: string, verse: string): string {
  if (!text || !chapter || !verse) {
    return text;
  }
  const escaped = `${chapter}:${verse}`.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
  const midRe = new RegExp(`${escaped}\\. [\\s\\S]*?\\.(?=\\s+[a-z])`, 'g');
  let result = text.replace(midRe, ' ');
  const endRe = new RegExp(`\\s*${escaped}\\. [\\s\\S]*$`, 'g');
  result = result.replace(endRe, '');
  return result.replace(/\s+/g, ' ').trim();
}

/**
 * Clean Spanish verse text by removing embedded cross-references and verse numbers
 * This is specifically for Reina Valera 1909 which includes inline references like:
 * "EN el 1.1 Sal. 136.5. Jn. 1.1-3. Col. 1.16,17. principio crió Dios..."
 *
 * Pattern examples:
 * - "1.1 Sal. 136.5. Jn. 1.1-3. Col. 1.16,17. He. 1.10 y 11.3."
 * - "1.2 Jer. 4.23."
 * - "1.3 2 Co. 4.6."
 * - "1.9 2 P. 3.5."
 * - "1.16 Sal. 136.7,8,9."
 * - "1.21 Sal. 104.26."
 * - "1.22 cp. Gn. 8.17 y 9.1."
 */
export const cleanSpanishVerseText = (text: string, translation?: string): string => {
  if (!text || translation !== 'es-rv09') {
    return text; // Only clean Spanish RV09 text
  }

  let cleaned = text;

  // Remove verse number + book reference patterns
  // Pattern: verse number (e.g., "1.1", "1.2") followed by one or more book references
  // Book references: book abbreviation + chapter.verse patterns
  // Examples: "1.1 Sal. 136.5. Jn. 1.1-3.", "1.2 Jer. 4.23.", "1.16 Sal. 136.7,8,9."

  // First, handle complex multi-reference patterns like "1.1 Sal. 136.5. Jn. 1.1-3. Col. 1.16,17."
  // This regex matches a verse number followed by multiple book references
  // Handles numbered books like "2 Co.", "2 P.", "1 Jn.", etc.
  cleaned = cleaned.replace(
    /\d+\.\d+(?:\s+(?:cp\.\s*)?(?:\d+(?:\s+[a-z]{1,2})?)?\s*[A-Z][a-z]{0,3}(?:\s+[A-Z][a-z]{0,2})?\.?\s+\d+\.\d+(?:[-–]\d+)?(?:\s*,\s*\d+)*(?:\s+y\s+\d+\.\d+)?\.?)+\.?\s*/g,
    '',
  );

  // Handle verse number + "ver." (verse) and "vers." (verses) references
  // Examples: "1.14 ver. 7.", "1.18 vers. 2,3."
  cleaned = cleaned.replace(/\d+\.\d+\s+vers?\.\s+\d+(?:,\s*\d+)*\.\s*/g, '');

  // Handle verse number + "Esto es," (This is,) explanatory notes
  // Examples: "1.20 Esto es, Placentera.", "1.20 Esto es,"
  // Pattern: verse number + "Esto es," + optional explanatory text ending with period
  cleaned = cleaned.replace(/\d+\.\d+\s+Esto\s+es,?\s*(?:[A-Z][^.]*\.)?\s*/g, '');

  // Handle verse number + "cp." references without book abbreviations
  // Examples: "1.26 cp. 5.1 y 9.6.", "1.26 cp. 9.2.", "1.27 cp. 5.2.", "1.29 cp. 9.3.", "1.15 cp. 22.4, etc."
  // "2.1 cp. 1.29,35,43.", "2.2 cp. 1.40,42,43,45.", "2.25 cp. 6.61,64 y 13.11 y 21.17."
  cleaned = cleaned.replace(
    /\d+\.\d+\s+cp\.\s+\d+\.\d+(?:\s*,\s*\d+)*(?:\s+etc\.)?(?:\s+y\s+\d+\.\d+(?:\s*,\s*\d+)*)*\.\s*/g,
    '',
  );

  // Handle standalone "cp." references (without verse number prefix)
  // Examples: "cp. 4.12.", "cp. 1.29,35,43.", "cp. 6.4 y 11.55."
  cleaned = cleaned.replace(
    /\bcp\.\s+\d+\.\d+(?:\s*,\s*\d+)*(?:\s+etc\.)?(?:\s+y\s+\d+\.\d+(?:\s*,\s*\d+)*)*\.\s*/g,
    '',
  );

  // Handle standalone chapter.verse references (without book abbreviations or verse number prefix)
  // Examples: "39.9,10."
  cleaned = cleaned.replace(/\b\d+\.\d+(?:,\s*\d+)+\.\s*/g, '');

  // Handle simpler patterns: verse number + single book reference
  // Examples: "1.2 Jer. 4.23.", "1.3 2 Co. 4.6.", "1.9 2 P. 3.5."
  // Handles numbered books: \d+(?:\s+[a-z]{1,2})? matches "2 " or "1 " before book abbreviations
  cleaned = cleaned.replace(
    /\d+\.\d+\s+(?:cp\.\s*)?(?:\d+(?:\s+[a-z]{1,2})?)?\s*[A-Z][a-z]{0,3}(?:\s+[A-Z][a-z]{0,2})?\.?\s+\d+\.\d+(?:[-–]\d+)?(?:\s*,\s*\d+)*(?:\s+y\s+\d+\.\d+)?\.\s*/g,
    '',
  );

  // Remove standalone book references (without verse numbers)
  // Examples: "Sal. 136.7,8,9.", "Sal. 104.26.", "2 Co. 4.6."
  cleaned = cleaned.replace(
    /(?:cp\.\s*)?(?:\d+(?:\s+[a-z]{1,2})?)?\s*[A-Z][a-z]{0,3}(?:\s+[A-Z][a-z]{0,2})?\.?\s+\d+\.\d+(?:[-–]\d+)?(?:\s*,\s*\d+)*(?:\s+y\s+\d+\.\d+)?\.\s*/g,
    '',
  );

  // Clean up spacing
  cleaned = cleaned.replace(/\s+/g, ' ').trim();

  // Fix spacing around periods - ensure proper spacing after periods
  cleaned = cleaned.replace(/\s+\./g, '.');
  cleaned = cleaned.replace(/\.([A-Za-záéíóúñü])/g, '. $1');
  cleaned = cleaned.replace(/\.\./g, '.');

  return cleaned;
};

/**
 * Strip Diodati 1885 (Italian) inline reference notes from verse text.
 * Handles: verseRef + word + refs (e.g. 1.1 terra Sal. 33.6. Giov. 1.1-3. ...),
 * standalone book refs (Giov. 1.1-3. Col. 1.16.), and verse numbers attached to words (acque3, tenebre.5).
 */
export const cleanItalianVerseText = (text: string, translation?: string): string => {
  if (!text || translation !== 'it-db1885') {
    return text;
  }

  let cleaned = text;

  // 1) Verse ref + optional word + one or more book refs (allow verse ranges like 1.1-3) ending with .: or .. or ., or .
  const refBlockPattern =
    '\\d+\\.\\d+\\s+(?:[\\w\u00C0-\u017F]+\\s+)?' +
    '(?:(?:(?:\\d+\\s+)?[A-Za-z]+\\d*\\s*\\.\\s*)?\\d+\\.\\d+(?:\\s*[-–]\\s*\\d+)?(?:\\s*,\\s*\\d+)*(?:\\s*;\\s*\\d+\\.\\d+(?:\\s*,\\s*\\d+)*)*\\.?\\s*(?:ecc\\.?)?\\s*;?\\s*|\\d+\\s+ecc\\.?\\s*;?\\s*)+' +
    '(\\.:|\\.\\.|\\.,\\s*|\\.\\s*)';
  const refBlock = new RegExp(refBlockPattern, 'g');
  cleaned = cleaned.replace(refBlock, ' ');

  // 2) Remove standalone book refs (e.g. Giov. 1.1-3. Col. 1.16. Ebr. 1.10; 11.3.) that were left behind
  const standaloneRefPattern =
    '(?:[A-Za-z]+\\d*\\s*\\.\\s*)?\\d+\\.\\d+(?:\\s*[-–]\\s*\\d+)?(?:\\s*;\\s*\\d+\\.\\d+)*(?:\\s*,\\s*\\d+)*\\.?\\s*';
  const standaloneRef = new RegExp(standaloneRefPattern, 'g');
  cleaned = cleaned.replace(standaloneRef, ' ');

  // 3) Remove verse ref attached to word (e.g. pastore23.1, mancherà23.1)
  cleaned = cleaned.replace(/([\w\u00C0-\u017F]+)(\d+\.\d+)(?=\s|$)/g, '$1');

  // 4) Remove verse number (1-2 digits) or .verse attached to word (e.g. acque3, fu4, tenebre.5, giorno.6)
  cleaned = cleaned.replace(/([\w\u00C0-\u017F]+)(\.?\d{1,2})(?=\s|[A-Z])/g, '$1');

  // Normalize spaces and fix double spaces
  cleaned = cleaned.replace(/\s+/g, ' ').trim();
  cleaned = cleaned.replace(/\s+\./g, '.');
  cleaned = cleaned.replace(/\.\./g, '.');

  return cleaned;
};

/** Run translation-specific verse cleaning (Spanish RV09, Italian Diodati, etc.). */
export const cleanVerseText = (text: string, translation?: string): string => {
  return cleanSpanishVerseText(cleanItalianVerseText(text, translation), translation);
};
