// Update to use environment variables for API URLs
const WP_API_URL = process.env.REACT_APP_WP_API_URL;
const CUSTOM_API_URL = process.env.REACT_APP_WP_API_URL_CUSTOM;

const getAuthHeaders = (token?: string, isFormData = false): Record<string, string> => {
  const wpToken = token ?? Cookies.get('wpToken');
  const headers: Record<string, string> = isFormData ? {} : { 'Content-Type': 'application/json' };

  if (wpToken) {
    headers.Authorization = `Bearer ${wpToken}`;
  }

  return headers;
};

