export const saveStudyNote = async (note: Omit<StudyNote, 'id'>): Promise<StudyNote> => {
  const userId = Cookies.get('userId');
  if (!userId) {
    throw new Error('User not authenticated');
  }

  try {
    const response = await fetch(`${CUSTOM_API_URL}/study-notes`, {
      method: 'POST',
      headers: getAuthHeaders(),
      body: JSON.stringify({
        ...note,
        status: 'publish',
        author: parseInt(userId),
      }),
    });

    if (!response.ok) {
      throw new Error('Failed to save study note');
    }

    return response.json();
  } catch (error) {
    devError('Failed to save study note.');
    throw error;
  }
};

export const getUserStudyNotes = async (): Promise<StudyNote[]> => {
  const userId = Cookies.get('userId');
  if (!userId) {
    throw new Error('User not authenticated');
  }

  try {
    const response = await fetch(`${CUSTOM_API_URL}/study-notes?author=${userId}&per_page=100`, {
      headers: getAuthHeaders(),
    });

    if (!response.ok) {
      throw new Error('Failed to fetch study notes');
    }

    return response.json();
  } catch (error) {
    devError('Failed to fetch study notes.');
    throw error;
  }
};

