import { z } from 'zod';

import { stripFbvCommentary } from '../utils/bibleTextUtils';

/** App translation cookie id → bible-api folder on CDN / public/search */
export const translationToBibleFolder: Readonly<Record<string, string>> = {
  kjv: 'en-kjv',
  fbv: 'en-fbv',
  cuv: 'cuv-zh-hant',
  lut: 'lut',
  'es-rv09': 'es-rv09',
  'it-db1885': 'it-db1885',
  'cs-bkr': 'cs-bkr',
  'sv-skb': 'sv-skb',
  'id-tsi': 'id-tsi',
  'nl-nld1939': 'nl-nld1939',
  'vi-ovcb': 'vi-ovcb',
};

const CDN_BASE = 'https://cdn.jsdelivr.net/gh/revelationaryonline/bible-api/bibles';

const KJVAPP_SEARCH_URL: Readonly<Partial<Record<string, string>>> = {
  kjv: 'https://kjvapp.com/api/search?text=',
  cuv: 'https://cuv.kjvapp.com/api/search?text=',
  lut: 'https://lut.kjvapp.com/api/search?text=',
};

const SearchIndexEntrySchema = z.object({
  b: z.string(),
  c: z.number().int().positive(),
  v: z.number().int().positive(),
  t: z.string(),
});

const SearchIndexEntryLenientSchema = z.object({
  b: z.string(),
  c: z.number().or(z.string()),
  v: z.number().or(z.string()),
  t: z.string(),
});

const SearchIndexSchema = z.array(SearchIndexEntrySchema);

const VerseSearchResultSchema = z.object({
  id: z.number().or(z.string()),
  book: z.string(),
  chapter: z.number().or(z.string()),
  verse: z.number().or(z.string()),
  text: z.string(),
});

const KjvAppSearchResultsSchema = z.array(VerseSearchResultSchema);

export type VerseSearchResult = z.infer<typeof VerseSearchResultSchema>;

/** Normalise phrase-search hits for Dashboard `Verse` state. */
export function toDashboardVerse(result: VerseSearchResult): {
  book: string;
  chapter: number;
  verse: number;
  text: string;
  id: string;
} {
  return {
    id: String(result.id),
    book: result.book,
    chapter: Number(result.chapter),
    verse: Number(result.verse),
    text: result.text,
  };
}

const indexCache = new Map<string, VerseSearchResult[] | null>();
const indexLoadPromises = new Map<string, Promise<VerseSearchResult[] | null>>();

/** Warm the search index in the background (call on app load / translation change). */
export function prefetchBibleSearchIndex(translation: string): void {
  const bibleFolder = getBibleFolder(translation || 'kjv');
  if (!indexCache.has(bibleFolder) && !indexLoadPromises.has(bibleFolder)) {
    void fetchSearchIndex(bibleFolder);
  }
}

/** Extract phrase inside double quotes, e.g. `"light"` → `light`. */
export function parseQuotedPhrase(term: string): string | null {
  const match = term.match(/"([^"]+)"/);
  const phrase = match?.[1]?.trim();
  return phrase && phrase.length > 0 ? phrase : null;
}

export function isQuotedPhraseSearch(term: string): boolean {
  return (term.match(/"/g) ?? []).length >= 2 && parseQuotedPhrase(term) !== null;
}

function getBibleFolder(translation: string): string {
  return translationToBibleFolder[translation] ?? translationToBibleFolder.kjv;
}

function indexUrls(bibleFolder: string): string[] {
  return [`/search/${bibleFolder}.json`, `${CDN_BASE}/${bibleFolder}/search-index.json`];
}

function parseSearchIndexEntries(json: unknown): VerseSearchResult[] | null {
  if (!Array.isArray(json)) {
    return null;
  }

  const verses: VerseSearchResult[] = [];
  for (const item of json) {
    const parsed = SearchIndexEntryLenientSchema.safeParse(item);
    if (!parsed.success) {
      continue;
    }
    const chapter = Number(parsed.data.c);
    const verseNum = Number(parsed.data.v);
    if (!Number.isFinite(chapter) || !Number.isFinite(verseNum) || chapter < 1 || verseNum < 1) {
      continue;
    }
    const strict = SearchIndexEntrySchema.safeParse({
      b: parsed.data.b,
      c: chapter,
      v: verseNum,
      t: parsed.data.t,
    });
    if (strict.success) {
      verses.push(entryToVerse(strict.data, verses.length + 1));
    }
  }

  return verses.length > 0 ? verses : null;
}

function normalizeBookName(book: string): string {
  return book.trimEnd();
}

function entryToVerse(
  entry: z.infer<typeof SearchIndexEntrySchema>,
  id: number,
): VerseSearchResult {
  return {
    id,
    book: normalizeBookName(entry.b),
    chapter: entry.c,
    verse: entry.v,
    text: entry.t,
  };
}

async function fetchSearchIndex(bibleFolder: string): Promise<VerseSearchResult[] | null> {
  if (indexCache.has(bibleFolder)) {
    return indexCache.get(bibleFolder) ?? null;
  }

  const pending = indexLoadPromises.get(bibleFolder);
  if (pending) {
    return pending;
  }

  const loadPromise = (async (): Promise<VerseSearchResult[] | null> => {
    for (const url of indexUrls(bibleFolder)) {
      try {
        const response = await fetch(url);
        if (!response.ok) {
          continue;
        }
        const json: unknown = await response.json();
        const verses = parseSearchIndexEntries(json);
        if (verses) {
          indexCache.set(bibleFolder, verses);
          return verses;
        }
      } catch {
        // try next URL
      }
    }

    indexCache.set(bibleFolder, null);
    return null;
  })();

  indexLoadPromises.set(bibleFolder, loadPromise);
  try {
    return await loadPromise;
  } finally {
    indexLoadPromises.delete(bibleFolder);
  }
}

function searchIndex(verses: VerseSearchResult[], phrase: string): VerseSearchResult[] {
  const needle = phrase.toLowerCase();
  return verses.filter((verse) => verse.text.toLowerCase().includes(needle));
}

function sanitizeKjvAppQuery(term: string): string {
  return term.replace(/[^\u4e00-\u9fa5a-zA-Z0-9áéíóúñüäöüßÄÖÜ .,_"-]/gim, '').trim();
}

async function searchViaKjvApp(
  term: string,
  translation: string,
): Promise<VerseSearchResult[] | null> {
  const baseUrl = KJVAPP_SEARCH_URL[translation];
  if (!baseUrl) {
    return null;
  }

  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(), 8000);

  try {
    const response = await fetch(`${baseUrl}${encodeURIComponent(sanitizeKjvAppQuery(term))}`, {
      signal: controller.signal,
    });
    if (!response.ok) {
      return null;
    }
    const json: unknown = await response.json();
    const parsed = KjvAppSearchResultsSchema.safeParse(json);
    if (!parsed.success || parsed.data.length === 0) {
      return null;
    }
    return parsed.data.map((verse, index) => ({
      ...verse,
      id: verse.id ?? index + 1,
      book: normalizeBookName(String(verse.book)),
    }));
  } catch {
    return null;
  } finally {
    clearTimeout(timeoutId);
  }
}

/**
 * Search the active Bible translation for a quoted word or phrase.
 * Uses CDN search-index.json when available, otherwise falls back to kjvapp.com (kjv/cuv/lut).
 */
export async function searchBiblePhrase(
  term: string,
  translation: string,
): Promise<VerseSearchResult[]> {
  const phrase = parseQuotedPhrase(term);
  if (!phrase) {
    return [];
  }

  const bibleFolder = getBibleFolder(translation || 'kjv');
  const index = await fetchSearchIndex(bibleFolder);
  if (index) {
    return searchIndex(index, phrase);
  }

  const kjvAppResults = await searchViaKjvApp(term, translation || 'kjv');
  return kjvAppResults ?? [];
}

export function clearSearchIndexCache(): void {
  indexCache.clear();
}

/** Used by the index generator script. */
export function compactVerseForIndex(
  book: string,
  chapter: number | string,
  verse: number | string,
  text: string,
  translation: string,
): z.infer<typeof SearchIndexEntrySchema> {
  const chapterStr = String(chapter);
  const verseStr = String(verse);
  const cleanedText =
    translation === 'fbv' ? stripFbvCommentary(text, chapterStr, verseStr) : text.trim();

  return {
    b: normalizeBookName(book),
    c: Number(chapter),
    v: Number(verse),
    t: cleanedText,
  };
}

export { SearchIndexEntrySchema, SearchIndexSchema };
